     };

     const patterns = {
       email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
       phone: /^\+?[0-9()\-\s]{7,20}$/
     };

     function FormField({ id, label, type, placeholder, value, error, helperText = "" }) {
       const helperId = helperText ? id + "-helper" : "";
       const errorId = id + "-error";
       const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${id}">${label}</label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             placeholder="${placeholder}"
             value="${escapeHtml(value)}"
             aria-invalid="${error ? "true" : "false"}"
             ${describedBy ? `aria-describedby="${describedBy}"` : ""}
           />
           ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
           <p class="error-text" id="${errorId}" aria-live="polite">${error || ""}</p>
         </div>
       `;
     }

     function ContactForm() {
       return `
         <main class="page-shell">
           <section class="card" aria-labelledby="support-heading">
             <p class="eyebrow">Support</p>
             <h1 id="support-heading">Get in touch with our support team</h1>
             <p class="intro">Share your question and the best way to reach you. Required fields are marked with validation guidance as you type.</p>

